assert(dispatchRoute.includes("options.forceCompression === true || Boolean(target) || shouldCompressVideoReferenceImages()"), "video reference preparation should resize whenever a target size is supplied");
assert(dispatchRoute.includes("resizeVideoReferenceToTargetCanvas"), "target-sized video reference preparation should preserve the full frame on a provider-sized canvas");
assert(dispatchRoute.includes("resizeVideoReferenceToTargetCanvasWithFfmpeg"), "target-sized video references should fall back to ffmpeg-static when sharp cannot load on the production host");
assert(dispatchRoute.includes("function ffmpegExecutablePath()"), "video worker should resolve ffmpeg-static from the release root instead of trusting Next's bundled route path");
assert(dispatchRoute.includes('path.join(process.cwd(), "node_modules", "ffmpeg-static"'), "ffmpeg-static fallback should survive Next production route bundling");
assert(dispatchRoute.includes("video_reference_resize_ffmpeg_fallback_failed"), "ffmpeg reference resize fallback failures should be logged before the worker fails the job");
assert(dispatchRoute.includes('fit: "inside"') && dispatchRoute.includes("composite([{ input: foreground, gravity: \"center\" }]"), "target-sized video references should keep the whole source image centered instead of hard-cropping it");
assert(!dispatchRoute.includes('? { width: target.width, height: target.height, fit: "cover", position: "attention" }'), "target-sized video references should not directly cover-crop mismatched source ratios");
assert(dispatchRoute.includes("ai_provider_video_reference_resize_failed_"), "video reference resize failures should fail explicitly");
assert(!dispatchRoute.includes("options.fallbackToOriginal !== false"), "video reference resize should not silently fall back to uploading the original image");
assert(dispatchRoute.includes("size: providerRequestSize"), "multipart OpenAI-compatible video requests should send a provider-supported output size");
assert(dispatchRoute.includes("function openAiVideoCreateEndpoint("), "OpenAI-compatible video create endpoint should be selected per provider");
assert(dispatchRoute.includes("function proxyOpenAiVideoBaseUrl("), "proxy OpenAI-compatible video endpoints should normalize provider base URLs");
assert(dispatchRoute.includes('trimmed.replace(/\\/v1$/, "")'), "proxy video providers should not double-append /v1 when the configured base URL already includes it");
assert(dispatchRoute.includes("openAiVideoStatusEndpoint(params.baseUrl, params.taskId)"), "proxy video status polling should use the normalized videos endpoint");
assert(dispatchRoute.includes("openAiVideoContentEndpoint(params.baseUrl ?? \"\", params.taskId ?? \"\")"), "proxy video downloads should use the normalized content endpoint");
assert(dispatchRoute.includes("endpoint: new URL(endpoint).pathname"), "video create failures should report the actual create endpoint path");
assert(dispatchRoute.includes('AI_WORKER_GROK_IMAGINE_VIDEO_REFERENCE_MODE'), "Grok Imagine Video should default to JSON data URI references with an explicit multipart escape hatch");
assert(dispatchRoute.includes('if (explicitMode === "multipart" || explicitMode === "form") return false;'), "SmartPickLid JSON video requests should honor the multipart escape hatch");
assert(dispatchRoute.includes("const useProxyStringReferences = usesProxyOpenAiVideoEndpoint(params.baseUrl)"), "all proxy Grok video providers should use string image/images references");
assert(dispatchRoute.includes("proxyStringReferences: useProxyStringReferences"), "proxy reference mode should be passed into the JSON video reference payload");
assert(dispatchRoute.includes("if (imageUrls.length > 1) return { images: imageUrls };"), "proxy Grok video multi-reference requests should use the documented images string array");
assert(dispatchRoute.includes("return imageUrls.length ? { image: imageUrls[0] } : {};"), "proxy Grok video single-reference requests should use the documented image string field");
assert(dispatchRoute.includes("function shouldUseSharpForVideoReferenceImages()"), "video reference preparation should be able to disable sharp separately from generic image preparation");
assert(dispatchRoute.includes("LOCAL_AI_WORKER_VIDEO_REFERENCE_USE_SHARP"), "video reference sharp usage should have a production-safe override");
assert(dispatchRoute.includes("json_reference_images") && dispatchRoute.includes("json_image"), "Grok Imagine Video request diagnostics should identify JSON image and reference image payloads");
assert(!minimalVideoPromptFunction.includes("Internal video quality system"), "active video provider prompt should not mark backend rules as mandatory guidance");
assert(!minimalVideoPromptFunction.includes("Prompt hierarchy: ordered frame images and subject identity first"), "active video provider prompt should not add prompt-hierarchy wording");
assert(!minimalVideoPromptFunction.includes("Anatomy and motion guardrails"), "active video provider prompt should not add anatomy guardrail expansion");
assert(!minimalVideoPromptFunction.includes(".slice(0, 3600)") && !minimalVideoPromptFunction.includes(".slice(0, 4200)") && !minimalVideoPromptFunction.includes(".slice(0, 1800)"), "video provider prompt should not truncate the user's prompt to an arbitrary worker limit");
assert(
  !dispatchRoute.includes("generateLocalFallbackVideo") &&
    !dispatchRoute.includes("local_video_fallback_started") &&
    !dispatchRoute.includes("Local video fallback"),
  "video worker should not depend on local fallback output"
);

assert(siteStore.includes("assetRules: { min: 0, max: DEFAULT_VIDEO_FRAME_LIMIT"), "default video workflow should allow text-to-video while using the shared frame limit");
assert(siteStore.includes("videoWorkflowConfigWithCurrentFrameLimit") && siteStore.includes("videoWorkflowConfigWithCurrentFrameLimit(existingApp.workflowConfig)"), "existing video workflow configs should be lifted from legacy 4-frame limits");
assert(siteStore.includes("maxFrames: DEFAULT_VIDEO_FRAME_LIMIT"), "default video themes should use shared frame limit");
assert(siteStore.includes('slug: "prompt-directed-motion"'), "default video themes should include a neutral prompt-directed preset");
assert(siteStore.includes("ensurePromptDirectedDefaultVideoThemeRelational"), "existing sites should backfill the neutral prompt-directed video preset");

const schema = read("prisma/schema.prisma");
assert(schema.includes("maxFrames       Int                 @default(30)"), "Prisma schema should default video themes to 30 frames");

const migration = read("prisma/migrations/20260712043000_raise_video_frame_limit/migration.sql");
assert(migration.includes('ALTER TABLE "VideoTheme" ALTER COLUMN "maxFrames" SET DEFAULT 30'), "migration should raise maxFrames default");
assert(migration.includes('WHERE "maxFrames" < 30'), "migration should lift existing legacy limits");

